  'sponsor.costs.microsoft.title': 'Microsoft Partner Center',
  'sponsor.costs.microsoft.desc': 'Necessário para assinar e publicar a versão para a Microsoft Store.',
  'sponsor.costs.hosting.title': 'Hospedagem e domínio',
  'sponsor.costs.hosting.desc': 'Mantém este site e seus downloads no ar.',
  'sponsor.free.title': 'Formas gratuitas de ajudar',
  'sponsor.free.desc': 'Nem toda contribuição precisa ser financeira. Uma estrela ou uma recomendação também ajudam.',
  'sponsor.free.star': 'Dê uma estrela no GitHub',
